{
  "watch1": {
    "scenarios": [
      "features/conformance/item-element-identity.feature:A single item toggle preserves the item element instance",
      "features/conformance/item-element-identity.feature:The mark-all toggle preserves every item element instance",
      "features/conformance/editing-hides-controls.feature:Editing mode hides the non-edit controls"
    ]
  }
