/* TodoMVC vanilla implementation (Shipshape voyage).
 * State lives in localStorage under "tasks-vanilla"; the active filter lives
 * under "todo-filter". Rendering is the single source of truth for the DOM. */
(function () {
  'use strict';

  var doc = window.document;
  var store = window.localStorage;
  var loc = window.location;

  var STORAGE_KEY = 'tasks-vanilla';
  var FILTER_KEY = 'todo-filter';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var tasks = [];
  var filter = 'all';
  var editingId = null;
  var idSeq = 0;
  var bound = false;

  /** @planks("the app is open") */
  /** @planks("the task list is empty") */
  /** @planks("the app reloads") */
  function boot() {
    tasks = loadTasks();
    filter = currentFilter();
    editingId = null;
    render();
  }

  function uid() {
    idSeq += 1;
    return 't' + Date.now().toString(36) + '-' + idSeq;
  }

  function loadTasks() {
    try {
      var raw = store.getItem(STORAGE_KEY);
      if (!raw) return [];
      var data = JSON.parse(raw);
      return Array.isArray(data) ? data : [];
    } catch (e) {
      return [];
    }
  }

  /** @planks("localStorage holds a .* entry") */
  /** @planks("the .* entry is a JSON array") */
  /** @planks("each stored item has an .* field") */
  function saveTasks() {
    store.setItem(STORAGE_KEY, JSON.stringify(tasks));
  }

  function currentFilter() {
    var hash = loc.hash.replace(/^#\/?/, '');
    if (hash === 'active' || hash === 'completed' || hash === 'all') return hash;
    var saved = store.getItem(FILTER_KEY);
    if (saved === 'active' || saved === 'completed' || saved === 'all') return saved;
    return 'all';
  }

  function visibleTasks() {
    if (filter === 'active') return tasks.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return tasks.filter(function (t) { return t.completed; });
    return tasks;
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function linkName(a) {
    return (a.getAttribute('href') || '').replace(/^#\/?/, '');
  }

  /** @planks("the task list contains .* and .*") */
  /** @planks("the task list contains .*") */
  /** @planks("the task list contains .* tasks of which .* are active") */
  /** @planks("the main region is hidden") */
  /** @planks("the footer region is hidden") */
  /** @planks("the new task field has focus") */
  /** @planks("the list shows .*") */
  /** @planks("the list item .* is present") */
  /** @planks("the task .* is present") */
  /** @planks("the task .* is not present") */
  /** @planks("the mark-all control is checked") */
  /** @planks("the mark-all control is unchecked") */
  /** @planks("the task .* is in editing mode") */
  /** @planks("the edit field for .* has focus") */
  /** @planks("the task .* is not in editing mode") */
  /** @planks("the counter reads .*") */
  /** @planks("the clear completed control is hidden") */
  /** @planks("the clear completed control is shown") */
  /** @planks("the task .* is visible") */
  /** @planks("the task .* is not visible") */
  /** @planks("the .* filter link is selected") */
  function render() {
    var main = doc.querySelector('.main');
    var footer = doc.querySelector('.footer');
    var list = doc.querySelector('.todo-list');
    var toggleAll = doc.querySelector('#toggle-all');
    var count = doc.querySelector('.todo-count');
    var clear = doc.querySelector('.clear-completed');

    var hasTasks = tasks.length > 0;
    main.hidden = !hasTasks;
    footer.hidden = !hasTasks;

    var active = tasks.filter(function (t) { return !t.completed; }).length;
    var completed = tasks.length - active;

    if (toggleAll) {
      toggleAll.checked = hasTasks && active === 0;
      if ('indeterminate' in toggleAll) toggleAll.indeterminate = hasTasks && active > 0 && completed > 0;
    }

    list.innerHTML = visibleTasks().map(function (t) {
      var cls = [];
      if (t.completed) cls.push('completed');
      if (t.id === editingId) cls.push('editing');
      return '<li class="' + cls.join(' ') + '" data-id="' + t.id + '">' +
        '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
        '<label>' + escapeHtml(t.title) + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(t.title) + '">' +
        '</li>';
    }).join('');

    var noun = active === 1 ? 'item' : 'items';
    count.innerHTML = '<strong>' + active + '</strong> ' + noun + ' left';

    if (clear) clear.hidden = completed === 0;

    var links = doc.querySelectorAll('.filters a');
    for (var i = 0; i < links.length; i++) {
      var name = linkName(links[i]);
      if (name === filter) links[i].classList.add('selected');
      else links[i].classList.remove('selected');
    }

    if (editingId) {
      var editInput = list.querySelector('li.editing .edit');
      if (editInput) editInput.focus();
    } else {
      var newTodo = doc.querySelector('.new-todo');
      if (newTodo) newTodo.focus();
    }
  }

  /** @planks("the user types .* and presses Enter in the new task field") */
  /** @planks("the new task field is empty") */
  function addTask() {
    var input = doc.querySelector('.new-todo');
    var title = input.value.trim();
    if (title === '') return;
    tasks.push({ id: uid(), title: title, completed: false });
    input.value = '';
    saveTasks();
    render();
  }

  /** @planks("the task .* is marked completed") */
  /** @planks("the user checks the task .*") */
  function toggleTask(id) {
    for (var i = 0; i < tasks.length; i++) {
      if (tasks[i].id === id) { tasks[i].completed = !tasks[i].completed; break; }
    }
    saveTasks();
    render();
  }

  /** @planks("the user checks the mark-all control") */
  function toggleAllTasks(checked) {
    tasks.forEach(function (t) { t.completed = checked; });
    saveTasks();
    render();
  }

  /** @planks("the user double-clicks the task .*") */
  function startEdit(id) {
    editingId = id;
    render();
  }

  /** @planks("the user changes the edit field to .* and presses Enter") */
  /** @planks("the user changes the edit field to .* and blurs it") */
  function commitEdit(id, value) {
    var title = value.trim();
    if (title === '') { destroyTask(id); return; }
    for (var i = 0; i < tasks.length; i++) {
      if (tasks[i].id === id) { tasks[i].title = title; break; }
    }
    editingId = null;
    saveTasks();
    render();
  }

  /** @planks("the user changes the edit field to .* and presses Escape") */
  function cancelEdit() {
    editingId = null;
    render();
  }

  /** @planks("the user clicks clear completed") */
  /** @planks("the task .* is not present") */
  function clearCompleted() {
    tasks = tasks.filter(function (t) { return !t.completed; });
    saveTasks();
    render();
  }

  function destroyTask(id) {
    tasks = tasks.filter(function (t) { return t.id !== id; });
    saveTasks();
    render();
  }

  /** @planks("the active filter is .*") */
  /** @planks("the user opens the .* filter") */
  function setFilter(name) {
    if (name === '' || name === 'all' || name === 'active' || name === 'completed') {
      if (name === '') name = 'all';
      filter = name;
      loc.hash = '#/' + name;
      store.setItem(FILTER_KEY, name);
      render();
    }
  }

  function bind() {
    if (bound) return;
    bound = true;

    doc.addEventListener('keydown', function (e) {
      var target = e.target;
      if (target.classList.contains('new-todo') && e.key === 'Enter') {
        addTask();
      } else if (target.classList.contains('edit')) {
        var li = target.closest('li');
        var id = li ? li.getAttribute('data-id') : null;
        if (e.key === 'Enter') commitEdit(id, target.value);
        else if (e.key === 'Escape') cancelEdit();
      }
    });

    doc.addEventListener('change', function (e) {
      var target = e.target;
      if (target.classList.contains('toggle')) {
        var li = target.closest('li');
        if (li) toggleTask(li.getAttribute('data-id'));
      } else if (target.id === 'toggle-all') {
        toggleAllTasks(target.checked);
      }
    });

    doc.addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (!label) return;
      var li = label.closest('li');
      if (li) startEdit(li.getAttribute('data-id'));
    });

    doc.addEventListener('focusout', function (e) {
      var target = e.target;
      if (target.classList.contains('edit')) {
        var li = target.closest('li');
        if (li && li.getAttribute('data-id') === editingId) {
          commitEdit(li.getAttribute('data-id'), target.value);
        }
      }
    });

    doc.addEventListener('click', function (e) {
      var target = e.target;
      if (target.classList.contains('destroy')) {
        var li = target.closest('li');
        if (li) destroyTask(li.getAttribute('data-id'));
      } else if (target.classList.contains('clear-completed')) {
        clearCompleted();
      } else {
        var link = target.closest('.filters a');
        if (link) setFilter(linkName(link));
      }
    });

    window.addEventListener('hashchange', function () {
      filter = currentFilter();
      render();
    });
  }

  bind();
  boot();

  window.todoApp = { boot: boot, render: render, setFilter: setFilter };
})();

const { Given, When, Then } = require('@cucumber/cucumber');

function $(world, sel) {
  return world.document.querySelector(sel);
}

function $all(world, sel) {
  return Array.prototype.slice.call(world.document.querySelectorAll(sel));
}

function findTaskLi(world, title) {
  const lis = $all(world, '.todo-list li');
  for (let i = 0; i < lis.length; i++) {
    const label = lis[i].querySelector('label');
    if (label && label.textContent.trim() === title) return lis[i];
  }
  return null;
}

function editingInput(world) {
  return world.document.querySelector('li.editing .edit');
}

// ----- Setup (Given) -----

Given('the app is open', function () {
  if (!this.document.querySelector('.todoapp')) throw new Error('app is not open');
});

Given('the task list is empty', function () {
  this.setTasks([]);
});

Given(/^the task list contains "([^"]*)" and "([^"]*)"$/, function (a, b) {
  this.setTasks([
    { id: 'a', title: a, completed: false },
    { id: 'b', title: b, completed: false },
  ]);
});

Given(/^the task list contains "([^"]*)"$/, function (title) {
  this.setTasks([{ id: 'a', title: title, completed: false }]);
});

Given(/^the task list contains (\d+) tasks of which (\d+) are active$/, function (total, active) {
  total = parseInt(total, 10);
  active = parseInt(active, 10);
  const tasks = [];
  for (let i = 0; i < total; i++) {
    tasks.push({ id: 't' + i, title: 'Task ' + i, completed: i >= active });
  }
  this.setTasks(tasks);
});

Given(/^the task "([^"]*)" is marked completed$/, function (title) {
  const li = findTaskLi(this, title);
  if (!li) throw new Error('task not found: ' + title);
  if (!li.classList.contains('completed')) {
    const toggle = li.querySelector('.toggle');
    toggle.checked = true;
    toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }
  const after = findTaskLi(this, title);
  if (!after || !after.classList.contains('completed')) {
    throw new Error('task not completed: ' + title);
  }
});

Given(/^the active filter is "([^"]*)"$/, function (name) {
  this.setFilter(name);
});

// ----- Actions (When) -----

When(/^the user types "([^"]*)" and presses Enter in the new task field$/, function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When(/^the user checks the task "([^"]*)"$/, function (title) {
  const li = findTaskLi(this, title);
  if (!li) throw new Error('task not found: ' + title);
  const toggle = li.querySelector('.toggle');
  toggle.checked = true;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When(/^the user checks the mark-all control$/, function () {
  const t = this.document.querySelector('#toggle-all');
  t.checked = true;
  t.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When(/^the user double-clicks the task "([^"]*)"$/, function (title) {
  const li = findTaskLi(this, title);
  if (!li) throw new Error('task not found: ' + title);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When(/^the user changes the edit field to "([^"]*)" and presses Enter$/, function (text) {
  const edit = editingInput(this);
  if (!edit) throw new Error('no task in editing mode');
  edit.value = text;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
});

When(/^the user changes the edit field to "([^"]*)" and blurs it$/, function (text) {
  const edit = editingInput(this);
  if (!edit) throw new Error('no task in editing mode');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('focusout', { bubbles: true }));
});

When(/^the user changes the edit field to "([^"]*)" and presses Escape$/, function (text) {
  const edit = editingInput(this);
  if (!edit) throw new Error('no task in editing mode');
  edit.value = text;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
});

When(/^the user clicks clear completed$/, function () {
  const b = this.document.querySelector('.clear-completed');
  b.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

When(/^the user opens the "([^"]*)" filter$/, function (name) {
  this.window.location.hash = '#/' + name;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

When(/^the app reloads$/, function () {
  this.reload();
});

// ----- Assertions (Then) -----

Then(/^the main region is hidden$/, function () {
  if (this.document.querySelector('.main').hidden !== true) throw new Error('main region is not hidden');
});

Then(/^the footer region is hidden$/, function () {
  if (this.document.querySelector('.footer').hidden !== true) throw new Error('footer region is not hidden');
});

Then(/^the new task field has focus$/, function () {
  if (this.document.activeElement !== this.document.querySelector('.new-todo')) {
    throw new Error('new task field does not have focus');
  }
});

Then(/^the list shows (\d+) tasks?$/, function (n) {
  n = parseInt(n, 10);
  const count = this.document.querySelectorAll('.todo-list li').length;
  if (count !== n) throw new Error('expected ' + n + ' tasks, found ' + count);
});

Then(/^the list item "([^"]*)" is present$/, function (title) {
  if (!findTaskLi(this, title)) throw new Error('list item not present: ' + title);
});

Then(/^the task "([^"]*)" is present$/, function (title) {
  if (!findTaskLi(this, title)) throw new Error('task not present: ' + title);
});

Then(/^the task "([^"]*)" is not present$/, function (title) {
  if (findTaskLi(this, title)) throw new Error('task present but should not be: ' + title);
});

Then(/^the new task field is empty$/, function () {
  if (this.document.querySelector('.new-todo').value !== '') throw new Error('new task field is not empty');
});

Then(/^the mark-all control is checked$/, function () {
  if (this.document.querySelector('#toggle-all').checked !== true) throw new Error('mark-all control is not checked');
});

Then(/^the mark-all control is unchecked$/, function () {
  if (this.document.querySelector('#toggle-all').checked !== false) throw new Error('mark-all control is not unchecked');
});

Then(/^the task "([^"]*)" is in editing mode$/, function (title) {
  const li = findTaskLi(this, title);
  if (!li || !li.classList.contains('editing')) throw new Error('task not in editing mode: ' + title);
});

Then(/^the edit field for "([^"]*)" has focus$/, function (title) {
  const li = findTaskLi(this, title);
  if (!li) throw new Error('task not found: ' + title);
  if (this.document.activeElement !== li.querySelector('.edit')) {
    throw new Error('edit field for "' + title + '" does not have focus');
  }
});

Then(/^the task "([^"]*)" is not in editing mode$/, function (title) {
  const li = findTaskLi(this, title);
  if (li && li.classList.contains('editing')) throw new Error('task still in editing mode: ' + title);
});

Then(/^the counter reads "([^"]*)"$/, function (expected) {
  const text = this.document.querySelector('.todo-count').textContent.replace(/\s+/g, ' ').trim();
  if (text !== expected) throw new Error('counter reads "' + text + '", expected "' + expected + '"');
});

Then(/^the clear completed control is hidden$/, function () {
  if (this.document.querySelector('.clear-completed').hidden !== true) throw new Error('clear completed control is not hidden');
});

Then(/^the clear completed control is shown$/, function () {
  if (this.document.querySelector('.clear-completed').hidden !== false) throw new Error('clear completed control is not shown');
});

Then(/^the task "([^"]*)" is visible$/, function (title) {
  if (!findTaskLi(this, title)) throw new Error('task not visible: ' + title);
});

Then(/^the task "([^"]*)" is not visible$/, function (title) {
  if (findTaskLi(this, title)) throw new Error('task visible but should not be: ' + title);
});

Then(/^the "([^"]*)" filter link is selected$/, function (name) {
  const links = this.document.querySelectorAll('.filters a');
  let found = null;
  for (let i = 0; i < links.length; i++) {
    const n = (links[i].getAttribute('href') || '').replace(/^#\/?/, '');
    if (n === name) found = links[i];
  }
  if (!found) throw new Error('filter link not found: ' + name);
  if (!found.classList.contains('selected')) throw new Error('filter link not selected: ' + name);
});

Then(/^localStorage holds a "([^"]*)" entry$/, function (key) {
  if (this.window.localStorage.getItem(key) === null) throw new Error('no localStorage entry: ' + key);
});

Then(/^the "([^"]*)" entry is a JSON array$/, function (key) {
  const raw = this.window.localStorage.getItem(key);
  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    throw new Error('entry is not valid JSON: ' + key);
  }
  if (!Array.isArray(data)) throw new Error('entry is not a JSON array: ' + key);
});

Then(/^each stored item has an "([^"]*)", a "([^"]*)", and a "([^"]*)" field$/, function (f1, f2, f3) {
  const raw = this.window.localStorage.getItem('tasks-vanilla');
  const data = JSON.parse(raw);
  data.forEach(function (item) {
    [f1, f2, f3].forEach(function (f) {
      if (!(f in item)) throw new Error('stored item missing field: ' + f);
    });
  });
});

const fs = require('fs');
const path = require('path');
const { World, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = process.cwd();

function readTemplateBody() {
  const html = fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8');
  const m = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  let body = m ? m[1] : html;
  body = body.replace(/<script[\s\S]*?<\/script>/gi, '');
  body = body.replace(/<link[^>]*>/gi, '');
  return body;
}

const TEMPLATE_BODY = readTemplateBody();
const APP_SRC = fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8');

class TodoWorld extends World {
  constructor(options) {
    super(options);
    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.body.innerHTML = TEMPLATE_BODY;
    this.window.eval(APP_SRC);
  }

  boot() {
    if (this.window.todoApp && typeof this.window.todoApp.boot === 'function') {
      this.window.todoApp.boot();
    }
  }

  setTasks(tasks) {
    this.window.localStorage.setItem('tasks-vanilla', JSON.stringify(tasks));
    this.boot();
  }

  setFilter(name) {
    if (this.window.todoApp && typeof this.window.todoApp.setFilter === 'function') {
      this.window.todoApp.setFilter(name);
    }
  }

  reload() {
    this.document.body.innerHTML = TEMPLATE_BODY;
    this.boot();
  }
}

setWorldConstructor(TodoWorld);

After(function () {
  try {
    this.window.localStorage.clear();
  } catch (e) { /* ignore */ }
  try {
    this.window.close();
  } catch (e) { /* ignore */ }
});

#!/usr/bin/env node
// Shipwright-authored plank join + methodology conformance checker.
// The one checker Shipwright authors: it reports facts about the code that no
// runner reports (plank coverage, plank form, provisional drift) and carries
// the two required methodology conformance checks (watchbill-shape,
// perturbation-quiescence) plus the two text-pattern plank rules the
// Verification agreement obligates for a token-search annotation scan.
//
// Token-search fallback note (text-search weakness): the annotation scan below
// finds @planks/@planks-provisional tokens by regex over file text. It can miss
// a plank hidden inside a multiline string literal or a comment that is not a
// declaration-adjacent docblock, and it cannot tell whether a token sits in a
// docblock immediately preceding a declaration. A docblock/parser reader would
// close that gap; until one is installed this checker reports the join from
// token search and the two plank rules below keep the contract decidable.

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const RIGGING = path.join(ROOT, 'RIGGING.md');

function fail(msg) {
  console.error(`plank-join: ${msg}`);
  process.exit(1);
}

function readRiggingDirs() {
  if (!fs.existsSync(RIGGING)) fail('RIGGING.md not found; run fitting out first');
  const txt = fs.readFileSync(RIGGING, 'utf8');
  const impl = [];
  const specs = [];
  let section = null;
  for (const line of txt.split('\n')) {
    if (line.startsWith('## ')) {
      section = line.slice(3).trim();
      continue;
    }
    if (section !== 'Directories') continue;
    const m = line.match(/^-\s*(implementation|specs):\s*(.+?)\s*$/);
    if (m) {
      for (const v of m[2].split(/\s+/).filter(Boolean)) {
        (m[1] === 'implementation' ? impl : specs).push(v);
      }
    }
  }
  return { impl, specs };
}

function walk(dir) {
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...walk(p));
    else out.push(p);
  }
  return out;
}

function listFiles(dirs) {
  const out = [];
  for (const d of dirs) {
    const p = path.join(ROOT, d);
    if (!fs.existsSync(p)) continue;
    if (fs.statSync(p).isDirectory()) out.push(...walk(p));
    else out.push(p);
  }
  return out;
}

const PLANK_RE = /@planks(?:-provisional)?\(\s*"([^"]+)"\s*\)/g;

function collectPlanks(files) {
  const planks = [];
  for (const f of files) {
    if (!/\.(js|mjs|cjs|ts|tsx|html|vue|jsx)$/.test(f)) continue;
    const txt = fs.readFileSync(f, 'utf8');
    let m;
    PLANK_RE.lastIndex = 0;
    while ((m = PLANK_RE.exec(txt))) {
      const line = txt.slice(0, m.index).split('\n').length;
      const provisional = m[0].startsWith('@planks-provisional');
      planks.push({ file: f, line, pattern: m[1], provisional });
    }
  }
  return planks;
}

function collectStepPatterns(specs) {
  const patterns = [];
  for (const f of listFiles(specs)) {
    if (f.endsWith('.feature')) {
      const txt = fs.readFileSync(f, 'utf8');
      for (const line of txt.split('\n')) {
        const m = line.match(/^\s*(Given|When|Then|And|But)\s+(.+?)\s*$/);
        if (m) patterns.push({ text: m[2].trim(), file: f, bound: false });
      }
    } else if (/\.(js|mjs|cjs|ts)$/.test(f)) {
      const txt = fs.readFileSync(f, 'utf8');
      const re = /(Given|When|Then)\(\s*(`[^`]+`|'[^']+'|"[^"]+"|\/.*?\/)\s*\)/g;
      let m;
      while ((m = re.exec(txt))) {
        let p = m[2].replace(/^`|`$|^'|'$|^"|"$|^\/|\/$/g, '');
        patterns.push({ text: p, file: f, bound: true });
      }
    }
  }
  return patterns;
}

function normalize(s) {
  return s.replace(/\s+/g, ' ').trim();
}

function patternMatches(plankPat, stepText) {
  const a = normalize(plankPat);
  const b = normalize(stepText);
  if (a === b) return true;
  try {
    return new RegExp(plankPat).test(stepText);
  } catch {
    return false;
  }
}

function scenarioHasCaptain(ref, specs) {
  // ref form: <spec>.feature:<Scenario Name>
  const m = ref.match(/^(.+?):(.+)$/);
  if (!m) return false;
  const featurePath = path.join(ROOT, m[1]);
  if (!fs.existsSync(featurePath)) return false;
  const txt = fs.readFileSync(featurePath, 'utf8');
  const lines = txt.split('\n');
  let inTarget = false;
  for (const line of lines) {
    const tags = line.match(/^\s*@(\S+)/g);
    const scen = line.match(/^\s*Scenario:\s*(.+?)\s*$/);
    if (scen) {
      inTarget = normalize(scen[1]) === normalize(m[2]);
      continue;
    }
    if (/^\s*(Feature|Background|Rule|Scenario Outline|Examples):/.test(line)) {
      inTarget = false;
      continue;
    }
    if (inTarget && tags) {
      if (tags.some((t) => t.trim() === '@captain')) return true;
    }
  }
  return false;
}

function runJoin() {
  const { impl, specs } = readRiggingDirs();
  const planks = collectPlanks(listFiles(impl));
  const steps = collectStepPatterns(specs);
  const boundPatterns = steps.filter((s) => s.bound).map((s) => s.text);
  const violations = [];

  // plank-form: every plank pattern resolves to a current step pattern
  for (const pk of planks) {
    if (pk.provisional) {
      if (!scenarioHasCaptain(pk.pattern, specs)) {
        violations.push(`provisional plank names a scenario without @captain: ${pk.file}:${pk.line} -> ${pk.pattern}`);
      }
    } else if (!steps.some((s) => patternMatches(pk.pattern, s.text))) {
      violations.push(`plank matches no current step pattern: ${pk.file}:${pk.line} -> "${pk.pattern}"`);
    }
  }

  // plank-coverage: every behaviour-bearing (bound) step pattern has a plank
  for (const bp of boundPatterns) {
    if (!planks.some((pk) => !pk.provisional && patternMatches(pk.pattern, bp))) {
      violations.push(`behaviour-bearing step has no plank: "${bp}" (${steps.find((s) => s.text === bp)?.file})`);
    }
  }

  const join = {};
  for (const s of steps) {
    (join[s.text] ||= { scenarios: [], bound: s.bound });
    join[s.text].bound = s.bound || join[s.text].bound;
  }
  for (const pk of planks) {
    (join[pk.pattern] ||= { scenarios: [], bound: false, plank: [] });
    join[pk.pattern].plank = join[pk.pattern].plank || [];
    join[pk.pattern].plank.push(`${pk.file}:${pk.line}${pk.provisional ? ' (provisional)' : ''}`);
  }

  console.log(JSON.stringify({ planks: planks.length, stepPatterns: steps.length, bound: boundPatterns.length, join, violations }, null, 2));
  if (violations.length) fail(`${violations.length} plank-join violation(s)`);
  console.log('plank-join: clean');
  process.exit(0);
}

function checkWatchbillShape() {
  const f = path.join(ROOT, 'watchbill.json');
  if (!fs.existsSync(f)) {
    console.log('watchbill absent: conforms (deck at rest)');
    process.exit(0);
  }
  let data;
  try {
    data = JSON.parse(fs.readFileSync(f, 'utf8'));
  } catch (e) {
    fail(`watchbill.json is not valid JSON: ${e.message}`);
  }
  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    fail('watchbill.json must be an object of watch entries');
  }
  const tierTags = new Set(['@logic', '@sandbox']);
  const violations = [];
  const keys = Object.keys(data);
  const watchRe = /^watch\d+$/;
  for (const k of keys) {
    if (!watchRe.test(k)) {
      violations.push(`watch entry key "${k}" is not "watchN"`);
      continue;
    }
    const v = data[k];
    if (typeof v !== 'object' || v === null || Array.isArray(v) || !('scenarios' in v)) {
      violations.push(`watch "${k}" must be an object with a "scenarios" array`);
      continue;
    }
    if (!Array.isArray(v.scenarios)) {
      violations.push(`watch "${k}".scenarios must be an array`);
      continue;
    }
    for (const s of v.scenarios) {
      if (typeof s !== 'string') {
        violations.push(`watch "${k}" has a non-string scenario entry`);
        continue;
      }
      const isRef = /^[^\s].*\.feature:.*$/.test(s);
      const isTier = tierTags.has(s);
      if (!isRef && !isTier) {
        violations.push(`watch "${k}" entry "${s}" is neither a <spec>.feature:<Scenario> ref nor a tier tag`);
      }
    }
  }
  if (violations.length) fail(violations.join('; '));
  console.log('watchbill-shape: conforms');
  process.exit(0);
}

function checkPerturbationQuiescence() {
  const { impl } = readRiggingDirs();
  const found = [];
  for (const f of listFiles(impl)) {
    if (fs.readFileSync(f, 'utf8').includes('PERTURBATION')) found.push(f);
  }
  if (found.length) fail(`standing PERTURBATION token in: ${found.join(', ')}`);
  console.log('perturbation-quiescence: clean');
  process.exit(0);
}

const idx = process.argv.indexOf('--check');
const check = idx >= 0 ? process.argv[idx + 1] : null;
if (check === 'watchbill-shape') checkWatchbillShape();
if (check === 'perturbation-quiescence') checkPerturbationQuiescence();
if (check) fail(`unknown --check value: ${check}`);
runJoin();

